<?php
declare(strict_types=1);
require_once __DIR__.'/config_security.php';
/** Owner-managed JSON, never executable PHP. Key and ciphertext remain outside every known web root. */
function gszManagedDirectory():string {return __DIR__.'/server-config';}
function gszPrivateDirectory(string $dir):void {
 $parent=realpath(dirname($dir));if(!$parent||is_link($dir))throw new RuntimeException('GSZ_PRIVATE_PATH');$path=$parent.'/'.basename($dir);foreach([realpath(dirname(__DIR__).'/public'),(empty($_SERVER['DOCUMENT_ROOT'])?false:realpath((string)$_SERVER['DOCUMENT_ROOT']))] as $root)if($root&&($path===$root||str_starts_with($path,$root.'/')))throw new RuntimeException('GSZ_PRIVATE_WEBROOT');
 if(!is_dir($dir)&&!@mkdir($dir,0700))throw new RuntimeException('GSZ_PRIVATE_WRITE');if(is_link($dir)||realpath($dir)!==$path||!is_writable($dir))throw new RuntimeException('GSZ_PRIVATE_WRITE');@chmod($dir,0700);clearstatcache(true,$dir);if((fileperms($dir)&0077)!==0)throw new RuntimeException('GSZ_PRIVATE_PERMISSIONS');
}
function gszPrivateRead(string $path,int $max=200000):string {if(is_link($path)||!is_file($path)||!gszConfigSecurity($path)['safe']||filesize($path)>$max)throw new RuntimeException('GSZ_PRIVATE_READ');$s=file_get_contents($path);if($s===false)throw new RuntimeException('GSZ_PRIVATE_READ');return $s;}
function gszPrivateWrite(string $path,string $content):void {
