}
function gszManagedLoad():array {
 $dir=gszManagedDirectory();$file=$dir.'/managed.json';if(!file_exists($file))return [];gszPrivateDirectory($dir);$record=json_decode(gszPrivateRead($file),true,32,JSON_THROW_ON_ERROR);$key=gszPrivateRead($dir.'/managed.key',32);if(strlen($key)!==32||($record['version']??0)!==1)throw new RuntimeException('GSZ_MANAGED_CONFIG');$iv=base64_decode($record['iv']??'',true);$tag=base64_decode($record['tag']??'',true);$bytes=base64_decode($record['ciphertext']??'',true);if($iv===false||strlen($iv)!==12||$tag===false||strlen($tag)!==16||$bytes===false)throw new RuntimeException('GSZ_MANAGED_CONFIG');$plain=openssl_decrypt($bytes,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag,'GSZ-managed-v1');if($plain===false)throw new RuntimeException('GSZ_MANAGED_CONFIG');try{$data=json_decode($plain,true,32,JSON_THROW_ON_ERROR);if(!is_array($data)||array_is_list($data))throw new RuntimeException('GSZ_MANAGED_CONFIG');return $data;}finally{if(function_exists('sodium_memzero'))sodium_memzero($plain);}
}
function gszManagedSave(array $updates):void {
 if(!extension_loaded('openssl'))throw new RuntimeException('GSZ_OPENSSL_REQUIRED');$dir=gszManagedDirectory();gszPrivateDirectory($dir);if(is_link($dir.'/write.lock'))throw new RuntimeException('GSZ_PRIVATE_PATH');$lock=fopen($dir.'/write.lock','c+b');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('GSZ_CONFIG_BUSY');@chmod($dir.'/write.lock',0600);
 try{$existing=gszManagedLoad();$allowed=array_keys(require __DIR__.'/config.example.php');$allowed=[...$allowed,'managed_ignore_legacy'];foreach($updates as $k=>$v)if(!in_array($k,$allowed,true)||(!is_string($v)&&!is_int($v)&&!is_bool($v))||(is_string($v)&&strlen($v)>32000))throw new RuntimeException('GSZ_CONFIG_KEY');$values=array_replace($existing,$updates);$keyFile=$dir.'/managed.key';if(!file_exists($keyFile))gszPrivateWrite($keyFile,random_bytes(32));$key=gszPrivateRead($keyFile,32);if(strlen($key)!==32)throw new RuntimeException('GSZ_MANAGED_CONFIG');$iv=random_bytes(12);$tag='';$plain=json_encode($values,JSON_THROW_ON_ERROR);$bytes=openssl_encrypt($plain,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag,'GSZ-managed-v1');if($bytes===false)throw new RuntimeException('GSZ_CONFIG_ENCRYPT');gszPrivateWrite($dir.'/managed.json',json_encode(['version'=>1,'iv'=>base64_encode($iv),'tag'=>base64_encode($tag),'ciphertext'=>base64_encode($bytes)],JSON_THROW_ON_ERROR));}finally{flock($lock,LOCK_UN);fclose($lock);}
}
/** Remove obsolete keys (e.g. removed finance/banking settings). No-op without managed config. */
function gszManagedRemove(array $keys):int {
 $dir=gszManagedDirectory();if(!file_exists($dir.'/managed.json'))return 0;gszPrivateDirectory($dir);$lock=fopen($dir.'/write.lock','c+b');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('GSZ_CONFIG_BUSY');
 try{$existing=gszManagedLoad();$removed=0;foreach($keys as $k)if(array_key_exists($k,$existing)){unset($existing[$k]);$removed++;}if(!$removed)return 0;if(!$existing){@unlink($dir.'/managed.json');return $removed;}$key=gszPrivateRead($dir.'/managed.key',32);if(strlen($key)!==32)throw new RuntimeException('GSZ_MANAGED_CONFIG');$iv=random_bytes(12);$tag='';$bytes=openssl_encrypt(json_encode($existing,JSON_THROW_ON_ERROR),'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag,'GSZ-managed-v1');if($bytes===false)throw new RuntimeException('GSZ_CONFIG_ENCRYPT');gszPrivateWrite($dir.'/managed.json',json_encode(['version'=>1,'iv'=>base64_encode($iv),'tag'=>base64_encode($tag),'ciphertext'=>base64_encode($bytes)],JSON_THROW_ON_ERROR));return $removed;}finally{flock($lock,LOCK_UN);fclose($lock);}
}
